import fs from 'node:fs';
import path from 'node:path';

import { VITE_CONFIG_FILES } from '../utils/constants.ts';

export interface ConfigFiles {
  viteConfig?: string;
  vitestConfig?: string;
  tsdownConfig?: string;
  oxlintConfig?: string;
  oxfmtConfig?: string;
  eslintConfig?: string;
  eslintLegacyConfig?: string;
  prettierConfig?: string; // e.g. '.prettierrc.json', 'prettier.config.js', PRETTIER_PACKAGE_JSON_CONFIG
  prettierIgnore?: boolean;
  nvmrcFile?: boolean;
  voltaNode?: string;
}

// Sentinel value indicating Prettier config lives inside package.json "prettier" key.
export const PRETTIER_PACKAGE_JSON_CONFIG = 'package.json#prettier';

// All known Prettier config file names (standalone files only).
// https://prettier.io/docs/configuration
export const PRETTIER_CONFIG_FILES = [
  '.prettierrc',
  '.prettierrc.json',
  '.prettierrc.jsonc',
  '.prettierrc.yaml',
  '.prettierrc.yml',
  '.prettierrc.toml',
  '.prettierrc.js',
  '.prettierrc.cjs',
  '.prettierrc.mjs',
  '.prettierrc.ts',
  '.prettierrc.cts',
  '.prettierrc.mts',
  'prettier.config.js',
  'prettier.config.cjs',
  'prettier.config.mjs',
  'prettier.config.ts',
  'prettier.config.cts',
  'prettier.config.mts',
] as const;

export function detectConfigs(projectPath: string): ConfigFiles {
  const configs: ConfigFiles = {};

  for (const config of VITE_CONFIG_FILES) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.viteConfig = config;
      break;
    }
  }

  // Check for vitest.config.*
  // https://vitest.dev/config/
  const vitestConfigs = [
    'vitest.config.ts',
    'vitest.config.mts',
    'vitest.config.cts',
    'vitest.config.js',
    'vitest.config.mjs',
    'vitest.config.cjs',
  ];
  for (const config of vitestConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.vitestConfig = config;
      break;
    }
  }

  // Check for tsdown.config.*
  // https://tsdown.dev/options/config-file
  const tsdownConfigs = [
    'tsdown.config.ts',
    'tsdown.config.mts',
    'tsdown.config.cts',
    'tsdown.config.js',
    'tsdown.config.mjs',
    'tsdown.config.cjs',
    'tsdown.config.json',
    'tsdown.config',
  ];
  // Additionally, you can define your configuration directly in the `tsdown` field of your package.json file
  for (const config of tsdownConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.tsdownConfig = config;
      break;
    }
  }

  // Check for oxlint configs
  // https://oxc.rs/docs/guide/usage/linter/config.html#configuration-file-format
  const oxlintConfigs = ['.oxlintrc.json', '.oxlintrc.jsonc'];
  for (const config of oxlintConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.oxlintConfig = config;
      break;
    }
  }

  // Check for oxfmt configs
  // https://oxc.rs/docs/guide/usage/formatter.html#configuration-file
  const oxfmtConfigs = ['.oxfmtrc.json', '.oxfmtrc.jsonc'];
  for (const config of oxfmtConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.oxfmtConfig = config;
      break;
    }
  }

  // Check for eslint configs (flat config only)
  // https://eslint.org/docs/latest/use/configure/configuration-files
  const eslintConfigs = [
    'eslint.config.js',
    'eslint.config.mjs',
    'eslint.config.cjs',
    'eslint.config.ts',
    'eslint.config.mts',
    'eslint.config.cts',
  ];
  for (const config of eslintConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.eslintConfig = config;
      break;
    }
  }

  // Check for legacy eslint configs (.eslintrc*)
  // https://eslint.org/docs/latest/use/configure/configuration-files-deprecated
  const eslintLegacyConfigs = [
    '.eslintrc',
    '.eslintrc.json',
    '.eslintrc.js',
    '.eslintrc.cjs',
    '.eslintrc.yaml',
    '.eslintrc.yml',
  ];
  for (const config of eslintLegacyConfigs) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.eslintLegacyConfig = config;
      break;
    }
  }

  // Check for prettier configs
  for (const config of PRETTIER_CONFIG_FILES) {
    if (fs.existsSync(path.join(projectPath, config))) {
      configs.prettierConfig = config;
      break;
    }
  }
  // Check for .prettierignore
  if (fs.existsSync(path.join(projectPath, '.prettierignore'))) {
    configs.prettierIgnore = true;
  }

  // Check for .nvmrc (nvm)
  if (fs.existsSync(path.join(projectPath, '.nvmrc'))) {
    configs.nvmrcFile = true;
  }

  // Check package.json for "prettier" key and Volta node version
  const packageJsonPath = path.join(projectPath, 'package.json');
  if (fs.existsSync(packageJsonPath)) {
    try {
      const content = fs.readFileSync(packageJsonPath, 'utf8');
      const pkg = JSON.parse(content);

      if (!configs.prettierConfig && pkg.prettier) {
        configs.prettierConfig = PRETTIER_PACKAGE_JSON_CONFIG;
      }

      const voltaNode = pkg.volta?.node;
      if (typeof voltaNode === 'string') {
        configs.voltaNode = voltaNode;
      }
    } catch {
      // ignore parse errors
    }
  }

  return configs;
}

import { styleText } from 'node:util';

import * as prompts from '@voidzero-dev/vite-plus-prompts';

import { PackageManager, type WorkspacePackage } from '../types/index.ts';
import {
  detectAgentConflicts,
  detectExistingAgentTargetPaths,
  selectAgentTargetPaths,
} from '../utils/agent.ts';
import {
  detectEditorConflicts,
  type EditorId,
  isJsonLikeFile,
  selectEditor,
} from '../utils/editor.ts';
import { cancelAndExit, promptGitHooks } from '../utils/prompts.ts';
import {
  confirmEslintMigration,
  detectEslintProject,
  detectIncompatibleEslintIntegration,
  preflightGitHooksSetup,
  warnIncompatibleEslintIntegration,
  warnLegacyEslintConfig,
  warnPackageLevelEslint,
} from './migrator.ts';
import type { MigrationOptions } from './options.ts';

export interface MigrationSetupPlan {
  shouldSetupHooks: boolean;
  selectedAgentTargetPaths?: string[];
  agentConflictDecisions: Map<string, 'append' | 'skip'>;
  selectedEditor?: EditorId;
  editorConflictDecisions: Map<string, 'merge' | 'skip'>;
  migrateEslint: boolean;
  eslintConfigFile?: string;
}

async function collectGitHooksDecision(
  rootDir: string,
  packageManager: PackageManager | undefined,
  options: MigrationOptions,
  packages: readonly WorkspacePackage[] = [],
): Promise<boolean> {
  let shouldSetupHooks = await promptGitHooks(options);
  if (shouldSetupHooks) {
    const reason = preflightGitHooksSetup(rootDir, packageManager, packages);
    if (reason) {
      prompts.log.warn(`⚠ ${reason}`);
      shouldSetupHooks = false;
    }
  }
  return shouldSetupHooks;
}

async function collectAgentInstructionPlan(
  rootDir: string,
  options: MigrationOptions,
): Promise<{
  selectedAgentTargetPaths?: string[];
  agentConflictDecisions: Map<string, 'append' | 'skip'>;
}> {
  const existingAgentTargetPaths =
    options.agent !== undefined || !options.interactive
      ? undefined
      : detectExistingAgentTargetPaths(rootDir);
  const selectedAgentTargetPaths =
    existingAgentTargetPaths !== undefined
      ? existingAgentTargetPaths
      : await selectAgentTargetPaths({
          interactive: options.interactive,
          agent: options.agent,
          onCancel: () => cancelAndExit(),
        });

  const agentConflicts = await detectAgentConflicts({
    projectRoot: rootDir,
    targetPaths: selectedAgentTargetPaths,
  });
  const agentConflictDecisions = new Map<string, 'append' | 'skip'>();
  for (const conflict of agentConflicts) {
    if (options.interactive) {
      const action = await prompts.select({
        message:
          `Agent instructions already exist at ${conflict.targetPath}.\n  ` +
          styleText(
            'gray',
            'The Vite+ template includes guidance on `vp` commands, the build pipeline, and project conventions.',
          ),
        options: [
          { label: 'Append', value: 'append' as const, hint: 'Add template content to the end' },
          { label: 'Skip', value: 'skip' as const, hint: 'Leave existing file unchanged' },
        ],
        initialValue: 'skip' as const,
      });
      if (prompts.isCancel(action)) {
        cancelAndExit();
      }
      agentConflictDecisions.set(conflict.targetPath, action);
    } else {
      agentConflictDecisions.set(conflict.targetPath, 'skip');
    }
  }

  return { selectedAgentTargetPaths, agentConflictDecisions };
}

async function collectEditorConfigPlan(
  rootDir: string,
  options: MigrationOptions,
): Promise<{
  selectedEditor?: EditorId;
  editorConflictDecisions: Map<string, 'merge' | 'skip'>;
}> {
  const selectedEditor = await selectEditor({
    interactive: options.interactive,
    editor: options.editor,
    onCancel: () => cancelAndExit(),
  });

  const editorConflicts = detectEditorConflicts({
    projectRoot: rootDir,
    editorId: selectedEditor,
  });
  const editorConflictDecisions = new Map<string, 'merge' | 'skip'>();
  for (const conflict of editorConflicts) {
    if (options.interactive) {
      const action = await prompts.select({
        message:
          `${conflict.displayPath} already exists.\n  ` +
          styleText(
            'gray',
            'Vite+ adds editor settings for the built-in linter and formatter. Merge adds new keys without overwriting existing ones.',
          ),
        options: [
          {
            label: 'Merge',
            value: 'merge' as const,
            hint: 'Merge new settings into existing file',
          },
          { label: 'Skip', value: 'skip' as const, hint: 'Leave existing file unchanged' },
        ],
        initialValue: 'skip' as const,
      });
      if (prompts.isCancel(action)) {
        cancelAndExit();
      }
      editorConflictDecisions.set(conflict.fileName, action);
    } else {
      // Non-JSON files (e.g. JetBrains XML) can't be merged, so only skip them here.
      editorConflictDecisions.set(
        conflict.fileName,
        isJsonLikeFile(conflict.fileName) ? 'merge' : 'skip',
      );
    }
  }

  return { selectedEditor, editorConflictDecisions };
}

async function collectEslintMigrationDecision(
  rootDir: string,
  options: MigrationOptions,
  packages?: WorkspacePackage[],
): Promise<{ migrateEslint: boolean; eslintConfigFile?: string }> {
  const eslintProject = detectEslintProject(rootDir, packages);
  const incompatibleEslintIntegration = detectIncompatibleEslintIntegration(rootDir, packages);
  let migrateEslint = false;
  if (incompatibleEslintIntegration) {
    // e.g. `@nuxt/eslint` — skip the entire ESLint migration; preserve
    // the user's current ESLint setup and let them migrate by hand.
    warnIncompatibleEslintIntegration(incompatibleEslintIntegration);
  } else if (
    eslintProject.hasDependency &&
    !eslintProject.configFile &&
    eslintProject.legacyConfigFile
  ) {
    warnLegacyEslintConfig(eslintProject.legacyConfigFile);
  } else if (eslintProject.hasDependency && eslintProject.configFile) {
    migrateEslint = await confirmEslintMigration(options.interactive);
  } else if (eslintProject.hasDependency) {
    warnPackageLevelEslint();
  }

  return { migrateEslint, eslintConfigFile: eslintProject.configFile };
}

export async function collectMigrationSetupPlan(
  rootDir: string,
  packageManager: PackageManager | undefined,
  options: MigrationOptions,
  packages?: WorkspacePackage[],
  includeEslint = true,
): Promise<MigrationSetupPlan> {
  const shouldSetupHooks = await collectGitHooksDecision(
    rootDir,
    packageManager,
    options,
    packages,
  );
  const agentPlan = await collectAgentInstructionPlan(rootDir, options);
  const editorPlan = await collectEditorConfigPlan(rootDir, options);
  const eslintPlan = includeEslint
    ? await collectEslintMigrationDecision(rootDir, options, packages)
    : { migrateEslint: false };

  return {
    shouldSetupHooks,
    ...agentPlan,
    ...editorPlan,
    ...eslintPlan,
  };
}

import fs from 'node:fs';
import path from 'node:path';

import { runCommandSilently } from '../utils/command.ts';
import { type CommandRunSummary, runViteFmt } from '../utils/prompts.ts';
import { addMigrationWarning, type MigrationReport } from './report.ts';

type FormatRunner = (
  cwd: string,
  interactive?: boolean,
  paths?: string[],
  options?: { silent?: boolean; command?: string; commandArgs?: string[] },
) => Promise<CommandRunSummary>;

type FormatPathCollector = (
  cwd: string,
  excludedPaths?: ReadonlySet<string>,
) => Promise<string[] | undefined>;

interface FormatMigratedProjectOptions {
  format?: FormatRunner;
  collectPaths?: FormatPathCollector;
  excludedPaths?: ReadonlySet<string>;
}

const FORMAT_FAILURE_MESSAGE =
  'Automatic formatting failed. Run `vp fmt` manually after migration.';

// Keep each `vp fmt <...paths>` argument list well under the OS command-line
// limit. Migrating a large monorepo can rewrite thousands of files, so the
// path list is split into batches to avoid a spawn failure that would leave
// the migrated source unformatted. The limit differs sharply by platform:
// ARG_MAX is ~256KB on macOS, but Windows CreateProcess caps the whole joined
// command line at 32,767 characters (shared with the node path and CLI entry).
const MAX_FORMAT_ARG_BYTES = process.platform === 'win32' ? 24_000 : 100_000;

function chunkPathsByArgLength(paths: string[]): string[][] {
  const chunks: string[][] = [];
  let current: string[] = [];
  let currentBytes = 0;
  for (const filePath of paths) {
    const bytes = Buffer.byteLength(filePath) + 1; // +1 for the argument separator
    if (current.length > 0 && currentBytes + bytes > MAX_FORMAT_ARG_BYTES) {
      chunks.push(current);
      current = [];
      currentBytes = 0;
    }
    current.push(filePath);
    currentBytes += bytes;
  }
  if (current.length > 0) {
    chunks.push(current);
  }
  return chunks;
}

function parseNullDelimitedPaths(output: Buffer): string[] {
  return output.toString().split('\0').filter(Boolean);
}

function isExistingFile(projectRoot: string, relativePath: string): boolean {
  const absolutePath = path.join(projectRoot, relativePath);
  try {
    return fs.statSync(absolutePath).isFile();
  } catch {
    return false;
  }
}

/**
 * Limit automatic formatting to files changed in the current Git worktree.
 * This prevents migration from reformatting unrelated source trees while still
 * covering manifests, generated config, and rewritten imports.
 *
 * Return `undefined` outside a Git worktree so non-Git projects retain the
 * existing full-project formatting behavior.
 */
export async function collectChangedFormatPaths(
  projectRoot: string,
  excludedPaths?: ReadonlySet<string>,
): Promise<string[] | undefined> {
  try {
    const git = (args: string[]) =>
      runCommandSilently({ command: 'git', args, cwd: projectRoot, envs: process.env });

    // Only fall back to whole-project formatting when the project is genuinely
    // not a Git worktree. A worktree that exists but cannot enumerate changes
    // (locked repo, mid-rebase, unusual config) must NOT trigger a full-tree
    // reformat that would bury the migration diff.
    const worktree = await git(['rev-parse', '--is-inside-work-tree']);
    if (worktree.exitCode !== 0) {
      // rev-parse also exits 128 for failures inside a real worktree, e.g.
      // "detected dubious ownership" in Docker/CI checkouts. Only the genuine
      // "not a git repository" answer opts into whole-project formatting;
      // every other failure skips targeted formatting instead.
      return worktree.stderr.toString().includes('not a git repository') ? undefined : [];
    }
    if (worktree.stdout.toString().trim() !== 'true') {
      return undefined;
    }

    const [unstaged, staged, untracked] = await Promise.all([
      git(['diff', '--name-only', '--relative', '-z', '--diff-filter=ACMRTUXB', '--', '.']),
      git([
        'diff',
        '--cached',
        '--name-only',
        '--relative',
        '-z',
        '--diff-filter=ACMRTUXB',
        '--',
        '.',
      ]),
      git(['ls-files', '--others', '--exclude-standard', '-z', '--', '.']),
    ]);
    if (unstaged.exitCode !== 0 || staged.exitCode !== 0 || untracked.exitCode !== 0) {
      // Inside a worktree but Git could not list changes; skip targeted
      // formatting rather than reformatting the entire project.
      return [];
    }

    const changedPaths = new Set([
      ...parseNullDelimitedPaths(unstaged.stdout),
      ...parseNullDelimitedPaths(staged.stdout),
      ...parseNullDelimitedPaths(untracked.stdout),
    ]);

    // Oxfmt owns the supported-file list and skips unknown formats. Passing
    // every existing changed file keeps migration aligned as Oxfmt evolves.
    return [...changedPaths]
      .filter((file) => !excludedPaths?.has(file) && isExistingFile(projectRoot, file))
      .toSorted();
  } catch {
    // git itself is unavailable (spawn failure). Whether the project is a
    // worktree is unknowable here, so skip targeted formatting rather than
    // risking a full-tree reformat of a real repository.
    return [];
  }
}

/**
 * Do not apply Oxfmt to a project that still uses Prettier. Their formatting
 * rules can conflict, especially when Prettier is enforced through ESLint.
 */
export function canFormatWithOxfmt(
  hasPrettierDependency: boolean,
  prettierMigrated: boolean,
): boolean {
  return !hasPrettierDependency || prettierMigrated;
}

/**
 * Format a successfully migrated project without turning a formatter problem
 * into an unhandled migration failure. The formatter already prints its
 * stdout/stderr when it exits nonzero; the report keeps the manual follow-up
 * visible in the final migration summary.
 */
export async function formatMigratedProject(
  projectRoot: string,
  interactive: boolean,
  report: MigrationReport,
  options: FormatMigratedProjectOptions = {},
): Promise<boolean> {
  const { format = runViteFmt, collectPaths = collectChangedFormatPaths, excludedPaths } = options;
  try {
    const paths = await collectPaths(projectRoot, excludedPaths);
    if (paths?.length === 0) {
      return true;
    }
    const cliEntry = process.argv[1] ? path.resolve(process.cwd(), process.argv[1]) : undefined;
    const formatOptions = {
      silent: false,
      ...(cliEntry
        ? { command: process.execPath, commandArgs: [...process.execArgv, cliEntry] }
        : {}),
    };
    // `undefined` means "format the whole project" (single invocation); a path
    // list is batched so a huge monorepo cannot overflow the command line.
    const batches = paths === undefined ? [undefined] : chunkPathsByArgLength(paths);
    let allFormatted = true;
    for (const batch of batches) {
      const result = await format(projectRoot, interactive, batch, formatOptions);
      if (result.status !== 'formatted') {
        allFormatted = false;
        break;
      }
    }
    if (allFormatted) {
      return true;
    }
  } catch {
    // Treat spawn/config failures the same as a formatter nonzero exit. The
    // migration changes are still valid and the user can format them manually.
  }

  addMigrationWarning(report, FORMAT_FAILURE_MESSAGE);
  return false;
}

