  // `vite-plus`) is re-placed, then splice the new entry in sorted position.
  const entries: [string, string][] = Object.entries(pkg.devDependencies ?? {}).filter(
    ([name]) => name !== 'vite',
  );
  const insertAt = entries.findIndex(([name]) => name > 'vite');
